* 二创作者：玲
* 素材大部分为本人手搓，字素来源冰原YB，面板背景图来自柚见雪
* 改适配看🧧，代码比较混乱我也不知道为啥生效了。
适配关键词：token，计时器，楼层，头像，头图原高（气泡中间有一部分始终不显示搜这个），角色名，时间戳，编辑（小铅笔），正文顶部留空，底部间距或留空。
*/
/*字体🛑*/
@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
    font-family: "KingHwaOldSong";
    font-weight: normal;
}
/* === 一、全局控制 === */
:root {
  /* 主要颜色变量 */
  --main-text-color: #fff; /* 主要文字颜色 */


  --shadow-color: transparent; /* 文字阴影颜色 */
  --chat-tint-color: transparent; /* 聊天区域背景颜色 */
  --blur-tint-color: rgba(255, 255, 255, 0.1); /* 毛玻璃背景颜色 */
  --border-color: rgba(255, 255, 255, 1); /* 边框颜色 */
  --user-mes-blur-tint-color: transparent; /* 用户聊天气泡背景 */
  --bot-mes-blur-tint-color: transparent; /* AI聊天气泡背景 */
  --blur-strength: 0px; /* 背景模糊强度 */
  --message-bg-alpha: 0; /* 消息背景透明度 */

  /* 聊天气泡RGBA颜色变量 - 新增 */
  --user-bubble-color: rgba(0, 100, 255, 0.7); /* 用户气泡颜色 - 蓝色70%透明度 */
  --ai-bubble-color: rgba(100, 200, 100, 0.7); /* AI气泡颜色 - 绿色70%透明度 */
  --default-bubble-color: rgba(255, 255, 255, 0.8); /* 默认气泡颜色 - 白色80%透明度 */

  /* 聊天气泡底部背景层 - 新增 */
  --bubble-underlay-color: rgba(255, 255, 255, 0); /* 气泡背景透明度，改最后一个数字改成0.7都行 */
  --bubble-underlay-height: 100%; /* 气泡底部背景层高度 - 伪元素的一半 */

  --blur-strength: 0px; /* 背景模糊强度 */
  --message-bg-alpha: 0; /* 消息背景透明度 */

  /* 自定义变量 */
  --字体1: "不用填"; /* 主要字体 */
  --自定义思维链文案: "//"; /* 思维链自定义文案 */
  --自定义加载更多信息文案: "//"; /* 加载更多消息文案 */
  --自定义输入框文字: "//"; /* 输入框提示文字 */

  /* === 元素位置控制变量 === */
  /*头像位置🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧头像容器整体控制 */
  --avatar-container-top: -54px; /* 头像容器整体垂直位置 */
  --avatar-container-left: 35px; /* 头像容器整体水平位置 */
  --avatar-container-scale: 4.6; /* 头像大小🧧🧧🧧🧧🧧头像容器整体缩放 */

  /* 伪元素独立控制 */
  --pseudo-top: 100px; /* 伪元素顶部位置 */
  --pseudo-left: 50px; /* 伪元素水平位置 */
  --pseudo-width: 200px; /* 伪元素宽度 */
  --pseudo-height: 150px; /* 伪元素高度 - 调低避免重叠 */
  --pseudo-scale: 0.55; /* 伪元素缩放 */

  /* 头像在伪元素内定位 */
  --avatar-top: 65%; /* 头像在伪元素内的垂直位置 - 调整到右下角 */
  --avatar-left: 50%; /* 头像在伪元素内的水平位置 */
  --avatar-scale: 1; /* 头像缩放 */


  --mes-timer-top: 20px; /* 🧧计时器垂直位置 */
  --mes-timer-left: -3%; /* 🧧计时器水平位置 */
  --token-top: 20px; /* 🧧Token计数垂直位置 */
  --token-left: -38%; /* 🧧Token计数水平位置 */
  --mesid-top: 20px; /* 🧧楼层数垂直位置 */
  --mesid-left: -54%; /* 🧧楼层数水平位置 */
}


/* === 二、顶栏美化二改自@墨千尾 === */
/* === 二、顶栏美化 === */
#top-settings-holder {
  position: relative; /* 关键：让伪元素相对它定位 */
  background: none !important; /* 本身不设背景 */
  box-shadow: none !important;
  border-bottom: 0px solid #FFDB80;
  height: 30px; /* 你想让顶栏多高就设多高 */
  overflow: visible !important; /* 允许溢出 */
}

/* 背景图伪元素：溢出显示 */
#top-settings-holder::before {
  content: "";
  position: absolute;
  top: -0px;      /* 向上溢出50px，可调 */
  left: 0;
  width: 100vw;
  height: 100px;   /* 必须比90px高，才能“溢出” */
  background: url('https://iili.io/qHYjQyu.png') no-repeat center top / cover;
  z-index: -1;     /* 不被毛玻璃盖住 */
  pointer-events: none;
}

#top-settings-holder::after {
  content: "";
  position: absolute;
  inset: 0;
  backdrop-filter: blur(0px); /* 你想模糊就加，不想就0 */
  z-index: 0; /* 夹在背景和图标之间 */
  pointer-events: none;
}

/* 隐藏原有图标 */
#top-settings-holder .drawer-icon::before {
  content: '' !important; /* 清空原有内容 */
  visibility: hidden; /* 隐藏元素 */
}

#top-settings-holder .drawer {
  flex: 1; /* 弹性布局 */
}

#top-settings-holder .drawer-icon {
  display: block; /* 块级显示 */
  margin: 0 auto; /* 水平居中 */
  margin-top: 12px; /* 顶部间距 */
  background-size: contain; /* 背景图适应 */
  background-position: center; /* 背景图居中 */
  background-repeat: no-repeat; /* 不重复背景 */
  transition: all 0.3s ease-in-out; /* 过渡动画 */
  width: 40px; /* 图标宽度 */
  height: 40px; /* 图标高度 */
  opacity: 1 !important; /* 完全不透明 */
}

/* 悬停效果 */
.drawer-icon.fa-fw:hover {
  transform: scale(1.2); /* 悬停放大 */
}

/* 🛑🛑🛑🛑🛑🛑🛑🛑🛑🛑🛑🛑🛑🛑🧧🧧🧧🧧🧧🧧🧧🧧🧧顶栏图标替换 */
.drawer-icon.fa-sliders { background-image: url('https://iili.io/qHY4ujI.png'); } /* AI响应配置 */
.drawer-icon.fa-plug { background-image: url('https://iili.io/qHYOc2S.png'); } /* API连接 */
.drawer-icon.fa-font { background-image: url('https://iili.io/qHY6WRR.png'); } /* AI回复格式化 */
.drawer-icon.fa-book-atlas { background-image: url('https://iili.io/qHYP1XS.png'); } /* 世界信息 */
.drawer-icon.fa-user { background-image: url('https://iili.io/qHYiqG9.png'); } /* 用户设置 */
.drawer-icon.fa-image { background-image: url('https://iili.io/qHYihGt.png'); } /* 背景图 */
.drawer-icon.fa-cubes { background-image: url('https://iili.io/qHYs2Sa.png'); } /* 扩展 */
.drawer-icon.fa-bars-progress { background-image: url('https://iili.io/qHYs7Dl.png'); } /* 记忆表格 */
