.drawer-icon.fa-address-card { background-image: url('https://iili.io/qHY4ujI.png'); } /* 角色卡 */

/* ===== 2. 点击后图标（hover 用回各自原图）===== */
.drawer-icon.fa-sliders:hover { background-image: url('https://iili.io/qHYpXoJ.png'); }
.drawer-icon.fa-plug:hover { background-image: url('https://iili.io/qHYyiXa.png'); }
.drawer-icon.fa-font:hover { background-image: url('https://iili.io/qHa9jYN.png'); }
.drawer-icon.fa-book-atlas:hover { background-image: url('https://iili.io/qHaHvHB.png'); }
.drawer-icon.fa-user:hover { background-image: url('https://iili.io/qHaJzfj.png'); }
.drawer-icon.fa-image:hover { background-image: url('https://iili.io/qHaJwzX.png'); }
.drawer-icon.fa-cubes:hover { background-image: url('https://iili.io/qHaJymP.png'); }
.drawer-icon.fa-bars-progress:hover { background-image: url('https://iili.io/qHadNyB.png'); }
.drawer-icon.fa-face-smile:hover { background-image: url('https://iili.io/qHadbGs.png'); }
.drawer-icon.fa-address-card:hover { background-image: url('https://iili.io/qHYpXoJ.png'); }


#top-settings-holder,
#top-bar, /* 顶栏父容器 */
.header-container, /* 可能的外层容器 */
