    filter: drop-shadow(0 0 0 transparent) !important;
}
/* === 三、底栏美化@墨千尾 === */
/* 隐藏所有原始图标的伪元素 */
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#quick-reply-rocket-button > i {
  display: none !important; /* 隐藏元素 */
}

/* 统一设置所有图标按钮样式 */
#options_button,
#extensionsMenuButton,
#send_but,
#quick-reply-rocket-button {
  width: 30px; /* 图标宽度 */
  height: 30px; /* 图标高度 */
  background-size: contain; /* 背景图适应 */
  background-repeat: no-repeat; /* 不重复背景 */
  background-position: center; /* 背景图居中 */
  transition: transform 0.2s ease; /* 过渡动画 */
  font-size: 0; /* 隐藏文本 */
  border: none; /* 无边框 */
