/* 底栏悬浮效果 */
#form_sheld {
  position: absolute; /* 绝对定位 */
  bottom: 10px; /* 底部间距 */
}

#send_form {
  width: 86%; /* 底栏宽度 */
}


/* 底栏样式 */
#send_form, body.no-blur #send_form {
  position: relative;
  background-image: url('none');
  background-size: 100% 100%;
  background-position: center;
  border-radius: 0px;
  background-color: #fff !important;
  padding: 7px 12px;
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(0px);
  border: 1px solid #ff7d96; /* 外边框 */
  box-shadow: 0 0px 0px rgba(0, 0, 0, 0);
  transition: all 1s ease;
}
#send_form::before {
  content: "";
  position: absolute;
  inset: 2px; /* 上下左右各缩进2px = 外框与内框之间留出1px空隙 */
  border: 0.5px solid rgba(255, 125, 150, 1); /* 内边框 */
  pointer-events: none;
  border-radius: 0px;
}
/* 底栏悬停效果 */
#send_form:hover, body.no-blur #send_form:hover {
  transform: translateY(-5px); /* 上移效果 */
  background-color: rgba(255, 255, 255, 1) !important; /* 背景变浅 */
  box-shadow: 0 8px 30px rgba(255, 125, 150, 0.5); /* 阴影效果 */
  border: 0.5px solid #ff7d96 /* 保持边框 */
}

/* 底栏图标间距 */
#rightSendForm, #leftSendForm {
  gap: 5px; /* 图标间距 */
}

/* 输入框样式 */
#send_textarea {
  clip-path: none !important; /* 完整显示输入框 */
  border: none; /* 无边框 */
}

/* 方案1：彻底关掉 */
#send_form:focus-within {
    outline: none !important;
    box-shadow: 0 8px 30px rgba(255, 125, 150, 0.5) !important;
    border: 1px solid #ff7d96 !important;   /* 保持你自己设的边框 */
}
/* === 右上角装饰图标 === */
#send_form::after {
  content: "";
  position: absolute;
  top: -30px;          /* 向上偏移，让图标一半露出 */
  right: 40px;        /* 向右偏移 */
  width: 60px;         /* 装饰图标大小 */
  height: 60px;
  background: url('https://iili.io/qHa7BiG.png') center/contain no-repeat;
  pointer-events: none;/* 不挡点击 */
  z-index: 10;         /* 保证在最上层 */
}

/*右上角装饰@nini*/

#top-bar::after {
    content: '';
    display: block;
    width: 100%;
    height: 50px;
    background-image: url("留空");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: calc(100% - 0px) 0;   /* ← 只改这里 */
    margin-top: -2px;
    pointer-events: none;
    transform: scale(4);
    transform-origin: right top;
    z-index: -3;
}

/* === 四、聊天区域美化@墨千尾；@nini === */
/* 聊天区域背景透明 */
#chat {
  background-color: transparent !important; /* 透明背景 */
  backdrop-filter: none !important; /* 无模糊 */
  -webkit-backdrop-filter: none !important; /* Safari兼容 */
  padding: 0 !important; /* 无内边距 */
}

/* 聊天滚动容器透明 */
#chat,
#chat > div,
.chat-scroll-container,
.chat-messages-container {
  background-color: transparent !important; /* 透明背景 */
  background-image: auto !important; /* 无背景图 */
  border: none !important; /* 无边框 */
  outline: none !important; /* 无轮廓 */
}

/* Firefox滚动条兼容 */
.chat-scroll-container {
  scrollbar-color:  transparent !important; /* 透明滚动条 */
}

/* 🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗玲二改版聊天气泡 二改自@nini */
.mes {
    --w: 423px;          /* 🧧🧧头尾图宽度 */
    --gap: -210px;         /* 🧧🧧两条消息间距 */
    --head-h: 280px;     /* 气泡断层调小一点🧧🧧头图原高（占位用） */
    --foot-real: 8px;  /* 尾图原高（偏移量用） */
    --foot-show: 133px;  /* 🧧尾图你想显示的视觉高度，想调就改它 */

    max-width: var(--w);
    width: 98% !important;
    margin: calc(var(--head-h) + var(--gap)) auto var(--gap);
    position: relative;
    overflow: visible;
    background: none;
    border: none;
    box-shadow: none;

    /* 头图 */
    background-image: url("https://iili.io/qH7CeXS.png");
    background-repeat: no-repeat;
    background-position: center top;
    background-size: 100% auto;

    padding-top: var(--head-h);
    padding-bottom: var(--foot-real); /* 仍用真实高度占位 */
    padding-left: 20px;
    padding-right: 0;
}

/* 中间平铺层（只裁自己） */
.mes::before {
    content: "";
    position: absolute;
    inset: var(--head-h) 0 var(--foot-real) 0; /* 裁剪线用真实高度 */
    min-height:4px;
    background: url("https://iili.io/qH7o5tp.png") repeat-y;
    background-position:center 180px;
    background-size: 100% auto;
    z-index: -1;
    mask: linear-gradient(to bottom, transparent 0, black 1px, black 100%);
}

/* 尾图：尺寸与偏移量分离 */
.mes::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: calc(-1 * var(--foot-real)); /* 偏移仍用真实高度，保证拼接无缝 */
    height: var(--foot-show);            /* 视觉高度你想调就调 */
    background: url("https://iili.io/qH7x30X.png") no-repeat center bottom / 100% var(--foot-show);
    z-index: 2;
    pointer-events: none;
}


/* === 头像容器 - 整体控制（未改动） === */
.mes .mesAvatarWrapper {
