/* === 六、滚动条和滑动条美化@这对吗 === */
::-webkit-scrollbar {
    width: 0px; /* 🛑滚动条整体宽度，自调 */
    background-color: transparent; 
}
::-webkit-scrollbar-track {
    background-color: transparent; 
}
::-webkit-scrollbar-thumb {
  /* 方向（to bottom=从上到下）+ 颜色列表（用逗号分隔） */
  background-image: linear-gradient(to bottom, #462908, #462908, #462908);
  /* 如需渐变，比如上浅下深：linear-gradient(to bottom, #64a4c8, #4287a8) */
}

    border-radius: 10px;
    border: 0px; 
}

input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    width: 100%;
    background: transparent;
    cursor: pointer;
}
/* 2. 🛑设计滑块的“轨道”左右滑块 */
input[type="range"]::-webkit-slider-runnable-track {
    width: 100%;
    height: 6px; /* 轨道的粗细 */
    /* 轨道的背景现在是一个静态的、完整的渐变色，✨︎渐变颜色自调下边两个数值，调整原理和上边那个一样 ✨︎ */
    background: linear-gradient(to right, #fff, #ff9bae,#fff); 
    border-radius: 0px;
    border: 1px solid rgba(255, 125, 150, 0.1);
}

/* 3. 设计滑块的“手柄” (Thumb) - 使用自定义图标 */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;    
    margin-top: -15px; /* ✨︎图标（手柄）的上下距离，改了大小就要改这里哦，确保滑动的图标在滑动条上 ✨︎ */
    height: 35px; /* 高度 */
    width: 35px; /* 宽度 */

    /* ✨︎图标替换，自改✨︎ */
    background-image: url('https://iili.io/qHlAtm7.png');
    background-size: contain; /* 确保图标完整显示，不被拉伸 */
    background-repeat: no-repeat;
    background-position: center;

    /* 移除所有可能导致“变淡”的默认样式 */
    background-color: transparent; 
    border: none;
    border-radius: 0;
    box-shadow: none;
    transition: transform 0.2s ease; /* 保留悬停放大动画 */
}
/* 去除左右滑块阴影@玲 */
.neo-range-slider,
#temp_openai,
#freq_pen_openai,
#pres_pen_openai,
#top_p_openai,
#top_k_openai,
#openai_max_context {
  filter: none !important;
}



/* (可选) 4. 当鼠标悬停或拖动时，让手柄稍微变大 */
input[type="range"]:hover::-webkit-slider-thumb,
input[type="range"]:active::-webkit-slider-thumb {
    transform: scale(1.2);
}

/* 兼容Firefox浏览器 */
input[type="range"]::-moz-range-track {
    height: 6px; /* ✨︎图标（手柄）的上下距离✨︎ */
