}


/* ====== 通知弹窗最终美化补丁 ====== */
#toast-container .toast,
.toast {
    background-color: #fff !important;   /* 背景颜色 */
    color: #ff7d96 !important;              /*文字颜色 */
    box-shadow: none !important;            /* 去阴影 */
    border: 1px solid #ff7d96 !important;   /* 边框 */
    border-radius: 0px !important;         /* 保持圆角 */
    backdrop-filter: none !important;       /* 去毛玻璃（可选） */
