}

/* 强制把里层文字、图标一起改色 */
.toast-message,
.toast-title,
.toast * {
    color: #ff7d96 !important;
    -webkit-text-fill-color: #ff7d96 !important;
    text-shadow: none !important;
}
/* ====== 替换 Toast 左侧图标 ====== */
#toast-container > .toast {
    /* 去掉旧图标 */
    background-image: none !important;
    /* 新图标：居中、不重复、给文字留空 */
    background-image: url("https://iili.io/qHa7BiG.png") !important;
    background-size: 32px 32px !important;
    background-repeat: no-repeat !important;
    background-position: 15px center !important;
    /* 左侧留 52 px 给图标，防止文字重叠 */
    padding-left: 52px !important;
}
/* ====== Prompt Manager 单个预设条目 ====== */
#completion_prompt_manager_list > li.completion_prompt_manager_prompt {
    background: rgba(0,0,0,0) !important;   /* 背景颜色 */
