/* 
🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧
========= 顶部图片高度变量（统一调） ========== */
:root {
  --head-h: 5px;          /* 顶部图片高度，必须和原来 --head-h 一致 */
  --name-x: 73.2%;            /* 🛑名字水平位置（% / px / vw 都行） */
  --name-y: 30px;           /* 🛑名字垂直偏移（负数往上） */
  --date-x: 29.5%;            /* 🛑日期水平位置 */
  --date-y: 146px;           /* 日期垂直偏移 */

}

/* ========= 1. 文字容器整体拽上去 ========== */
.mes .mes_block {
  position: relative;              /* 给内部绝对定位当参照 */
  transform: translateY(-10px); /* 整体搬上去 */
  margin-top: 0 !important;        /* 清掉旧 margin */
  padding-top: var(--head-h);      /* 再补回顶部图片高度，正文不遮 */
}

/* ========= 三件套独立拖拽 ========== */
/* 名字：每个字垂直竖排 */
.mes .name_text {
  position: absolute !important;
  left: 50% !important;
  top: var(--name-y) !important;
  transform: translateX(-50%) !important;
  margin: 0 !important;
  /* 方案 1：浏览器默认的从左到右横排（最常用） */
  writing-mode: vertical-rl;
  text-orientation: upright;   /* 汉字正立不旋转 */
  font-size: 15px;
  color: var(--main-text-color);
  z-index: 10;
  pointer-events: none;
}

/* 前置伪元素（图标） */
.mes .name_text::before {
  content: "◎";               /* 想换图：content: url('https://...') */
  font-size: 13px;
  line-height: 1;
}


/* 真实日期 <small class="timestamp"> */
.mes small.timestamp {
  position: absolute !important;
  left: 50% !important;/*日期左右🧧🧧🧧🧧🧧*/
  bottom: 0px !important;/*jiu*/
  transform: translateX(-50%) !important;
  top: auto !important;/*日期高度🧧🧧🧧🧧🧧🧧🧧🧧*/
  right: auto !important;
  margin: 0 !important;
  white-space: nowrap;
  font-size: 11px;
  opacity: 0.7;
  color: var(--main-text-color);
  z-index: 10;
  pointer-events: none;
}

/* 前置文字 */
.mes small.timestamp::before {
  content: "『";
  color: inherit;
  margin-right: 4px;
}

/* 后置文字 */
.mes small.timestamp::after {
  content: "』";
  color: inherit;
  margin-left: 4px;
}

/* ===== 容器加宽，正文保持原宽 ===== */
:root {
  --mes-block-extra: 20px;   /* 🌟 容器左右各加多少 px */
  --mes-text-limit: 420px;   /* 🌟 正文最大宽度（原来 420 左右） */
}

/* 1. 文字容器左右外扩（不影响头像） */
.mes .mes_block {
  width: calc(100% + var(--mes-block-extra) * 2) !important;
  margin-left: calc(-1 * var(--mes-block-extra)) !important;
  margin-right: calc(-1 * var(--mes-block-extra)) !important;
}
/*🧧🧧🧧🧧🧧🧧正文宽度🧧🧧🧧🧧🧧🧧🧧*/
/* 2. 正文限制盒：居中+限宽 */
.mes .mes_text {
  max-width: var(--mes-text-limit) !important;
  margin: 0 auto !important;   /* 居中 */
  width: 86% !important;      /* 正文盒子宽度。让 max-width 生效 */
}
/* ===== 角色名+时间 字体 = 三元素同款 ===== */
:root{
  --name-color: #ff7893;   /* 与三元素一致 */
  --name-size: 13px;        /* 与三元素一致 */
  --date-color: #ff7893;   /* 与三元素一致 */
  --date-size: 12px;        /* 与三元素一致 */
}

/* 覆盖原主题那段 */
.mes .name_text{
    position: absolute !important;
    left: var(--name-x) !important;   /* 只保留这一条水平定位 */
    top: var(--name-y) !important;
    transform: none !important;       /* 关键：去掉居中偏移 */
    margin: 0 !important;
    white-space: nowrap;
    font-size: var(--name-size,11px);
    color: var(--name-color);
    z-index: 10;
    pointer-events: none;
}


/* 时间戳 <small class="timestamp"> */
.mes small.timestamp{
  color: var(--date-color) !important;
  font-size: var(--date-size) !important;
  font-weight: normal !important;
}
/* ===== 🛑🛑🛑🛑编辑消息图标（小铅笔）独立定位变量 ===== */
:root{
  --icon-right: 38px;   /* 🧧离右边距离 */
  --icon-top: 297px;     /* 🧧离顶部距离 */
  --icon-gap: 4px;     /* 🧧图标之间间距 */
}

/* 让整条按钮栏脱离文档流并贴边 */
.mes .mes_buttons{
  position: absolute !important;
  top: var(--icon-top) !important;
  right: var(--icon-right) !important;
  display: flex;
  flex-direction:row ;   /* 纵向排列column，想横向改成 row */
  gap: var(--icon-gap);
  z-index: 20;
}

/* 去掉原版多余 margin */
.mes .mes_buttons .mes_button{
  margin: 0 !important;
}
/* ===== 详细编辑栏 ===== */
:root{
  /* 微调口：觉得整体偏上就改小，偏下就改大 */
  --edit-bar-offset-top: 257px;   /* 
详细编辑栏高度负值 = 贴在正文盒外顶部；0 = 贴内顶部；正值 = 悬在上方更远 */
}

/* 1. 让正文盒成为统一参照 */
.mes .mes_text{
  position: relative !important;   /* 只当坐标系，不碰 padding/margin */
}

/* 2. 详细编辑栏绝对贴顶 + 水平居中 */
.mes_edit_buttons{
  position: absolute !important;
  top: var(--edit-bar-offset-top) !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  gap: 6px;
  z-index: 999;          /* 保证在最上层 */
  filter: none; /*移除阴影@易碎蝶*/
  pointer-events: all;   /* 确保可点 */
}

/* 3. 其余所有按钮栏一律隐藏，防止双份 */
.mes > .mes_buttons,
.mes .mes_block > .mes_buttons{
  display: none !important;
}
/* ===== 详细编辑栏高度🧧🧧🧧 → 只定位，不抢 display ===== */
:root{
  --edit-bar-top: 30px;   /* 想悬在正文盒上方 30px；贴顶就写 0 */
}

/* 只在“编辑中”状态才让它可见 + 定位 */
.mes.edit-mode .mes_edit_buttons{
  position: absolute !important;
  top: var(--edit-bar-top) !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  gap: 6px;
  z-index: 999;
  pointer-events: all;
}


/* ===== 🛑思维链 ===== */
:root{
  --rs: 273px;          /*思维链高度🧧🧧🧧 ↑↓ 只改这里，单位随便 em/px/rem */
}

/* 1. 把之前所有定位全清掉 */
.mes_reasoning,
.mes_reasoning_summary{
  position: relative !important;
  top: auto !important; left: auto !important; right: auto !important; bottom: auto !important;
  transform: translateY(var(--rs)) !important;   /* 唯一偏移口 */
  margin-left: 10% !important;                     /* 🛑水平居中 */
  width: 92% !important;
  max-width: 480px !important;
  z-index: 5 !important;                         /* 保证在文字层上方 */
}

/* 2. 让下拉箭头也同步走，不要分裂 */
.mes_reasoning_summary{
  transform: translateY(var(--rs)) !important
}

/* 3正文顶部留空🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧如果正文盒 padding 太大导致“看上去没动”，再减一点（可选） */
.mes .mes_text{
  padding-top: 299px !important;
}

/* ===== 思维链展开框 → 左右微调（不碰上下） ===== */
:root{
  --rs-offset-x: 15%;   /* 🛑左侧偏移：负值左移，正值右移；想居中写 0 */
}

/* 硬覆盖：只改水平位置，保留你原来 translateY 等垂直坐标 */
.mes_reasoning{
  position: relative !important;
  left: auto !important;
  right: auto !important;
  margin-left: var(--rs-offset-x) !important;
  margin-right: auto !important;
  width: 80% !important;
  max-width: 480px !important;
}
/* 1. 消息操作 —— 恢复默认图标，仅变蓝色，去阴影 */
.mes_button.extraMesButtonsHint.fa-solid.fa-ellipsis::before {
    content: "◎";          /* FontAwesome 省略号 */
}
.mes_button.extraMesButtonsHint.fa-solid.fa-ellipsis {
    background: none;
    width: auto; height: auto;
    color: #ff7893 !important; /* 颜色 */
    font-size: 15px;
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
}

/* 2. 编辑按钮 —— 恢复默认图标，仅变黄色，去阴影 */
.mes_button.mes_edit.fa-solid.fa-pencil::before {
    content: "◎";          /* FontAwesome 铅笔 */
}
.mes_button.mes_edit.fa-solid.fa-pencil {
    background: none;
    width: auto; height: auto;
    color: #ff7893 !important; /* 颜色 */
    font-size: 15px;
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
}

/* 3. 收藏按钮 —— 完全保持原样（文字/图标都不动）只去阴影 */
.mes_button.favorite-toggle-icon {
    background: none !important;
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
}
/* === 思维链编辑按钮整体位置，第一个左右第二个上下 15px === */
body:not(#_) .mes_reasoning_actions {
    transform: translate(-130px,35px);
}
/* 统一基础样式 */
.swipe_left,
.swipe_right {
  /* 把原来的字体图标隐藏掉 */
  font-family: none !important;
  content: none !important;

  /* 用背景图替代 */
  display: inline-block;
  width: 20px;          /* 按需调整 */
  height: 20px;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  cursor: pointer;
}

/* 左箭头 */
.swipe_left {
  background-image: url("https://iili.io/qHaxzqN.png");
}

/* 右箭头 */
.swipe_right {
  background-image: url("https://iili.io/qHaxzqN.png");
  opacity: 1;         /* 你原来就有透明度，保留 */
}
.TH-collapse-code-block-button {
  display: inline-block;
  padding: 6px 14px;
  font-size: 14px;
  line-height: 1.4;
  color: #ff7d96;
  background-color: #0000000a; /* 增加这一行 */
  border: none;
  border-radius: 4px;
  box-shadow: 0 2px 6px rgba(255,125,150,.25);
  cursor: pointer;
  transition: background .2s, box-shadow .2s;
}

/* ===== 弹窗本体 ===== */
dialog.popup.popup--animation-fast {
    background: #fff;          /* 窗口背景 */
    border: 1px solid #ff7d96;   /* 边框 */
    border-radius: 0px;
    box-shadow: none;            /* 去除阴影 */
    color: #ff7d96;                 /* 默认文字深灰，可自己改 */
}

/* ===== 正文容器 ===== */
dialog.popup .popup-content,
dialog.popup .popup-body {
    background: #fff;         /* 正文区域背景 */
}

/* ===== 红色按钮（是） ===== */
dialog.popup .popup-button-ok {
    background: #ff7d96 !important;         /* 底色 */
    color: #fff;              /* 字体颜色 */
    border: none;
    border-radius: 0px;
    padding: 6px 16px;
    cursor: pointer;
    transition: background .2s;
}
dialog.popup .popup-button-ok:hover {
    background: #ff7d96;         /* 悬停稍深 */
}

/* ===== 白色按钮（否） ===== */
dialog.popup .popup-button-cancel {
    background: #fff;         /* 底色 */
    color: #ff7d96;              /* 字体颜色 */
    border: 1px solid #ff7d96;  /* 边框 */
    border-radius: 0px;
    padding: 6px 16px;
    cursor: pointer;
    transition: background .2s, color .2s;
}
dialog.popup .popup-button-cancel:hover {
    background: #fff;
    color: #ff7d96;
}

/* ===== 关闭图标（如有） ===== */
dialog.popup .popup-button-close {
    color: #ff7d96;
}
/* ===== 漏掉的 textarea 单独补白 ===== */
textarea.alternate_greeting_text {
    background: #fff !important;   /* 背景颜色 */
    border: 0px solid #fff !important;
    border-radius: 4px;
    color: #ff7d96;                      /* 文字颜色，可改 */
    padding: 8px;
}
/* 统一白底 1px 边框 */
input[type="search"].text_pole,
input[type="text"].text_pole,
textarea.text_pole {
    background: #fff !important;
    border: 0px solid #462908 !important;
    border-radius: 0px;
    padding: 6px 8px;
    color: #ff7d96;          /* 文字颜色，想改就换 */
}
.completion_prompt_manager_prompt span span span {
    filter: none !important;
}


/*去除小黑点@nini*/
#send_textarea {
  resize: none; 
}

/* 让所有 hr 统一变成 2px 虚线，颜色随意改 */
hr {
    all: unset !important;
    display: block !important;
    border: none !important;
    border-top: 1px dashed var(--hr-color, #ff7d96) !important;
    margin: 20px 0 !important;
    opacity: var(--hr-opacity, .8) !important;
}

/* 复选框@蘑菇蟑螂汤 */
input[type="checkbox"] {
    -webkit-appearance: none;   /* 去掉默认样式 */
    appearance: none;
    background: url(https://iili.io/qHllT2s.png); /* 未选图 */
    background-size: contain;
    border: none;
    box-shadow: none;
    border-radius: 50%;
    width: 1.5em;
    height: 1.5em;
    outline: none;
}
input[type="checkbox"]:checked {
    background: url(https://iili.io/qHYpXoJ.png); /* 已选图 */
    background-size: contain;
    background-repeat: no-repeat;
}
/* 隐藏浏览器自带的白色对勾 */
input[type="checkbox"]::before,
input[type="checkbox"]::-webkit-check {
    content: none !important;
    display: none !important;
}

/* ===== 强制去圆角：气泡本身 ===== */
.mes,
.mes::before,
.mes::after,
.mes .mes_block,
.mes .mes_text {
    border-radius: 0 !important;
    overflow: visible !important;   /* 防止某些主题再裁掉尖角 */
}

/*🛑加载美化@墨千尾*/
#preloader {
  position: fixed;
  margin: 0;
  padding: 0;
  top: 0;
  left: 0;
  z-index: 999999;
  width: 100vw;
  height: 100vh;
  background: transparent;   /* 透明背景 */
}

#load-spinner {
  --spinner-size: 100px;
  --animation-duration-2x: 3s;
  position: absolute;
  top: calc(50% - var(--spinner-size) / 2);
  left: calc(50% - var(--spinner-size) / 2);
  width: var(--spinner-size);
  height: var(--spinner-size);
  animation: scaleAndStay var(--animation-duration-2x) infinite;
}

#load-spinner::before {
  content: "";
  position: absolute;
  inset: 0;
  background: url(https://iili.io/qHaxzqN.png) center/contain no-repeat;
  animation: upDown 1.2s ease-in-out infinite; /* 只上下动 */
}

/* 上下 10 px 循环（伪元素） */
@keyframes upDown {
  0%,100% { transform: translateY(0); }
  50%     { transform: translateY(-10px); }
}



/* 隐藏消息文本开头的所有br标签@P1222 */
.mes_text br:first-child,
.mes_text br:nth-child(2),
.mes_text br:nth-child(3) {
    display: none !important;
}

div:has(> span[data-i18n="Total Tokens:"]) {
  color: #ff7d96; /* 预设页面总词符数颜色 */
}
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
filter: none;
}

/* 头像容器脱离文档流，放大不再撑高父级 */
.mes .mesAvatarWrapper {
    position: absolute !important;   /* 已经写了，再保险一次 */
    transform: scale(var(--avatar-container-scale, 1)) !important;
    transform-origin: top left;
    /* 关键：让它不再占用任何布局空间 */
    top: 0;
    left: 0;
    width: 0 !important;
    height: 0 !important;
    overflow: visible;               /* 视觉依然可以溢出 */
}
/* ===== 三元素横向一排，手动偏移，不重叠 ===== */
.mesIDDisplay,
.tokenCounterDisplay,
.mes_timer {
    position: absolute !important;
    top: 16px !important;          /* 统一贴顶 */
    left: -8px !important;        /* 起点 */
    font-size: 1.8px !important;
    line-height: 1 !important;
    margin: 0 !important;
    white-space: nowrap;
    z-index: 10;
}

/* 第二条向右移 55px，第三条再移 55px，数值随你调🧧🧧🧧🧧🧧🧧🧧🧧🧧 */
.tokenCounterDisplay { transform: translateX(8px) !important; }
.mes_timer          { transform: translateX(16px) !important; }
